//! `README.md` of a Java target: how to use the generated package and how to regenerate it.
//!
//! The text is deterministic and holds no paths, hosts or dates (`CLAUDE.md` rule 2).

use veld_codegen::naming;
use veld_codegen::{FileSet, GenDiagnostic, GenRequest, Role};

use crate::util::add_file;

/// The exact bytes of `README.md`.
#[must_use]
pub fn render(base: &str, req: &GenRequest<'_>) -> String {
    let mut t = format!(
        "# Generated Java package `{base}`\n\nGenerated by Veld. DO NOT EDIT: changes are overwritten by the next `veld generate`.\n\n## Use\n\n"
    );
    t.push_str("Add this directory to your source path. It needs only the JDK (no other dependency).\n\n```java\n");
    for sid in &req.services {
        let svc = req.ir.service(*sid);
        let name = naming::pascal(&svc.name);
        match req.role {
            Role::Client => t.push_str(&format!(
                "import {base}.client.{name}Client;\n// var client = new {name}Client();\n"
            )),
            Role::Server => {
                if crate::events::serves_http(svc) {
                    t.push_str(&format!(
                        "import {base}.server.{name}Service;\n// implement {name}Service and serve it with {base}.server.{name}Handler\n"
                    ));
                }
                t.push_str(&crate::events::readme_lines(base, svc));
            }
        }
    }
    t.push_str("```\n\n");
    // The same text for every framework: a framework only adds files, it never changes the others.
    t.push_str("A server framework adapter (for example `spring`) adds its own files under `<base>.adapters`; they need that framework on the class path.\n\n");
    t.push_str("Values compare with `Veld.same(a, b)` (declaration signature plus canonical bytes), not with `equals`, when they may come from different generated packages.\n\n");
    t.push_str("## Regenerate\n\nRun `veld generate` in the project that holds `veld.toml`. The files listed in the manifest (`.veld-manifest.json` in this directory) are owned by Veld: a file you edited is kept, and generation refuses to overwrite it unless you pass `--force`.\n");
    t
}

/// Adds `README.md` to `files`.
pub fn emit(
    files: &mut FileSet,
    base: &str,
    req: &GenRequest<'_>,
) -> Result<(), Vec<GenDiagnostic>> {
    add_file(files, "README.md", render(base, req))
}
